const apiBase='/api';
const post=async(path,data)=>{const r=await fetch(`${apiBase}/${path}`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)});return r.json()};
const formObj=f=>Object.fromEntries(new FormData(f).entries());
const esc=v=>String(v??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[s]));
function extractAir(root){const out=[],seen=new Set();function walk(x){if(!x||typeof x!=='object')return;if(Array.isArray(x)){x.forEach(walk);return}const typ=String(x['@type']||x.type||'');if(/ProductAir|Flight/i.test(typ)||x.flightSegment||x.Segment||x.Carrier){const seg=x.flightSegment||x.Segment||x.flightSegments;let summary='Flight option';if(Array.isArray(seg))summary=seg.map(s=>`${s.origin||s.departure||s.From||''} → ${s.destination||s.arrival||s.To||''}`).join(' · ')||summary;else if(typeof x.description==='string')summary=x.description;const p=x.TotalPrice||x.totalPrice||x.Price||x.price;const key=JSON.stringify([summary,p]);if(!seen.has(key)){seen.add(key);out.push({summary,price:typeof p==='object'?(p?.value||p?.amount||p?.TotalPrice):p})}}Object.values(x).forEach(walk)}walk(root);return out}
const ff=document.getElementById('flightForm');ff?.addEventListener('submit',async e=>{e.preventDefault();const s=document.getElementById('flightStatus'),r=document.getElementById('flightResults');s.textContent='جاري البحث في Travelport…';r.innerHTML='';try{const j=await post('flight-search',formObj(ff));if(j.mode!=='live'){s.textContent=j.message||'محرك الطيران يحتاج إعدادات المزود.';return}const rows=extractAir(j.results);s.textContent=`تم استلام رد من Travelport${rows.length?` · ${rows.length} خيار`:''}`;r.innerHTML=rows.slice(0,20).map((x,i)=>`<article class="gb-card"><div style="font-size:35px;text-align:center">✈️</div><div><span class="gb-badge">TRAVELPORT</span><h3>خيار الرحلة ${i+1}</h3><p>${esc(x.summary)}</p><p>${x.price?`السعر: ${esc(x.price)}`:'السعر غير متاح في هذه الاستجابة'}</p></div><a class="gb-btn" href="https://wa.me/201155595342?text=${encodeURIComponent('أريد الاستفسار عن خيار طيران '+(i+1))}" target="_blank" rel="noopener">اطلب الحجز</a></article>`).join('')||'<p>تمت الاستجابة من Travelport، لكن لم تُرجع هذه الاستجابة بطاقات رحلة قابلة للعرض. سيتم تحويل الطلب لفريق JSM.</p>'}catch(err){s.textContent='تعذر الاتصال بمحرك الطيران.'}});
const hf=document.getElementById('hotelForm');hf?.addEventListener('submit',async e=>{e.preventDefault();const s=document.getElementById('hotelStatus'),r=document.getElementById('hotelResults');s.textContent='جاري البحث في محرك الفنادق…';r.innerHTML='';try{const d=formObj(hf);d.location=d.cityCode;const j=await post('hotel-search',d);if(j.mode!=='live'){s.textContent=j.message||'محرك الفنادق يحتاج إعدادات المزود.';return}const rows=j.results||[];s.textContent=`تم استلام ${rows.length} نتيجة من ${j.provider||'المزود'}`;r.innerHTML=rows.map((x,i)=>`<article class="gb-card">${x.image?`<img src="${esc(x.image)}" alt="${esc(x.name)}" loading="lazy">`:'<div></div>'}<div><span class="gb-badge">${esc(j.provider||'GLOBAL HOTEL')}</span><h3>${esc(x.name||'Hotel')}</h3><p>${esc(x.destination||d.cityCode)} ${x.stars?` · ${esc(x.stars)}★`:''}</p><p>${esc(x.description||'تتوفر التفاصيل حسب مزود الحجز.')}</p></div><button class="gb-btn" data-id="${esc(x.id||'')}" type="button">عرض الغرف</button></article>`).join('')||'<p>لا توجد نتائج.</p>';r.querySelectorAll('[data-id]').forEach(b=>b.onclick=async()=>{if(!b.dataset.id)return alert('لا يوجد hotelId في هذه النتيجة.');const j2=await post('hotel-rooms',{hotelId:b.dataset.id,checkIn:d.checkIn,checkOut:d.checkOut,adults:d.adults});alert(j2.mode==='live'?'تم جلب بيانات الغرف من مزود الحجز.':'تعذر جلب الغرف: '+(j2.message||''));});}catch(err){s.textContent='تعذر الاتصال بمحرك الفنادق.'}});
const pf=document.getElementById('packageForm');pf?.addEventListener('submit',async e=>{e.preventDefault();const s=document.getElementById('packageStatus');try{const d=formObj(pf);d.service_type='package_request';const j=await post('trip-request',d);s.textContent=j.reference?`تم تسجيل طلبك برقم ${j.reference}`:(j.message||'تم إرسال الطلب');pf.reset()}catch(err){s.textContent='تعذر تسجيل الطلب.'}});
